{"teaching_intent":"让学生把平抛看成水平匀速与竖直自由落体在同一物理时间中叠加：先以老师确认的 v0=12 m/s、y0=30 m、g=9.8 m/s² 暂停在 t=0，再拖动时间观察 x、y、vx、vy、加速度与动能/势能/机械能如何同步变化；随后只通过控件改变初速度、抛出方式/角度、高度、重力或质量，重新采样验证射程、飞行时间、最高点与能量守恒，而不在页面内手算公式。","html":"<!doctype html>
<html lang='zh-CN'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'>
<title>平抛与斜抛运动的分解与能量</title>
<style>
:root{--bg:#0f172a;--card:#111827;--ink:#e5e7eb;--muted:#94a3b8;--line:#334155;--blue:#38bdf8;--red:#fb7185;--green:#34d399;--orange:#fbbf24;--violet:#a78bfa}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#0b1120,#111827);color:var(--ink);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
main{max-width:1080px;margin:0 auto;padding:12px}h1{font-size:20px;margin:6px 0 10px}.grid{display:grid;grid-template-columns:1.35fr .9fr;gap:12px}.card{background:rgba(17,24,39,.92);border:1px solid var(--line);border-radius:14px;padding:12px;box-shadow:0 10px 28px rgba(0,0,0,.25)}
.controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ctl{min-height:54px;border:1px solid var(--line);border-radius:12px;padding:8px;background:#0b1220}.ctl label{display:flex;justify-content:space-between;font-size:13px;color:var(--muted);margin-bottom:6px}.ctl input,.ctl select{width:100%;min-height:44px;font-size:16px;color:var(--ink);background:#020617;border:1px solid #475569;border-radius:10px;padding:6px}input[type=range]{padding:0}.btns{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.btns button{min-height:44px;min-width:92px;border:0;border-radius:12px;background:#2563eb;color:white;font-size:16px;padding:10px 14px}.btns button.secondary{background:#334155}.read{font-variant-numeric:tabular-nums;line-height:1.65;color:#dbeafe}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 9px;margin:2px 4px 2px 0;background:#0b1220;color:#e0f2fe}.warn{color:#fde68a}.svgwrap{width:100%;overflow:hidden;border-radius:12px;background:#020617;border:1px solid #1e293b}svg{width:100%;height:auto;display:block}.legend{font-size:12px;color:var(--muted)}.bar{height:12px;border-radius:8px;background:#1f2937;overflow:hidden;margin:4px 0 8px}.bar i{display:block;height:100%;width:0}.k{background:var(--green)}.p{background:var(--violet)}.m{background:#e2e8f0}.note{color:#cbd5e1;font-size:13px}
@media(max-width:760px){.grid{grid-template-columns:1fr}.controls{grid-template-columns:1fr}h1{font-size:18px}}
</style>
</head>
<body>
<!--HARNESS_PRIMITIVES-->
<!--HARNESS_MODEL-->
<!--HARNESS_INPUT-->
<main>
<h1>平抛与斜抛运动的分解与能量</h1>
<div class='grid'>
<section class='card'>
<div class='svgwrap'><svg viewBox='0 0 760 370' role='img' aria-label='抛体运动视图'>
<defs><marker id='ar' markerWidth='9' markerHeight='9' refX='7' refY='3' orient='auto'><path d='M0,0 L8,3 L0,6 Z' fill='context-stroke'></path></marker></defs>
<rect x='0' y='0' width='760' height='370' fill='#020617'></rect>
<g id='axes' stroke='#475569' stroke-width='1'><line id='ground' x1='45' y1='320' x2='735' y2='320'></line><line id='yaxis' x1='70' y1='24' x2='70' y2='320'></line></g>
<path id='traj' fill='none' stroke='#e2e8f0' stroke-width='2.5' stroke-dasharray='5 4'></path>
<line id='xref' stroke='#38bdf8' stroke-dasharray='3 5' stroke-width='1.5'></line>
<line id='yref' stroke='#fb7185' stroke-dasharray='3 5' stroke-width='1.5'></line>
<circle id='projx' r='5' fill='#38bdf8'></circle><circle id='projy' r='5' fill='#fb7185'></circle>
<g id='ballg'><circle id='ball' r='10' fill='#f8fafc' stroke='#0ea5e9' stroke-width='3'></circle></g>
<line id='vxv' stroke='#38bdf8' stroke-width='4' marker-end='url(#ar)'></line>
<line id='vyv' stroke='#fb7185' stroke-width='4' marker-end='url(#ar)'></line>
<line id='vv' stroke='#34d399' stroke-width='3' marker-end='url(#ar)' opacity='.85'></line>
<line id='av' stroke='#fbbf24' stroke-width='4' marker-end='url(#ar)'></line>
<g font-size='12' fill='#cbd5e1' font-family='system-ui'><text id='lx' x='600' y='342'>水平分运动：x</text><text id='ly' x='20' y='40'>竖直分运动：y</text><text id='tvx' x='0' y='0'></text><text id='tvy' x='0' y='0'></text><text id='ta' x='0' y='0'>a=g 向下</text></g>
</svg></div>
<div class='legend'>蓝：x/vx　红：y/vy　绿：合速度　黄：加速度。虚线交点表示同一时刻两个分运动同时到达。</div>
<div class='btns'><button id='play'>播放</button><button id='pause' class='secondary'>暂停</button><button data-replay id='replay' class='secondary'>回放</button><button id='slow' class='secondary'>0.5×</button><button id='fast' class='secondary'>2×</button></div>
<div class='read'>
<span class='pill'>物理时间 <b data-physical-time id='pt'>0.000 s</b></span>
<span class='pill'>演示倍率 <b data-demo-time id='dt'>1.00×</b></span>
<span class='pill' data-readout id='ro'>等待采样</span>
</div>
</section>
<aside class='card'>
<div class='controls'>
<div class='ctl'><label><span>抛出方式</span><span id='modev'></span></label><select data-control data-mode id='mode'><option value='horizontal'>平抛 horizontal</option><option value='oblique'>斜抛 oblique</option></select></div>
<div class='ctl'><label><span>初速度 v0</span><span><b id='speedv'></b> m/s</span></label><input data-control data-speed id='speed' type='range' min='1' max='30' step='0.1'></div>
<div class='ctl'><label><span>角度 θ</span><span><b id='anglev'></b>°</span></label><input data-control data-angle id='angle' type='range' min='-75' max='75' step='1'></div>
<div class='ctl'><label><span>高度 y0</span><span><b id='y0v'></b> m</span></label><input data-control data-y0 id='y0' type='range' min='1' max='80' step='0.5'></div>
<div class='ctl'><label><span>重力 g</span><span><b id='gv'></b> m/s²</span></label><input data-control data-g id='g' type='range' min='1' max='20' step='0.1'></div>
<div class='ctl'><label><span>质量 m</span><span><b id='massv'></b> kg</span></label><input data-control data-mass id='mass' type='range' min='0.1' max='5' step='0.1'></div>
</div>
<hr style='border-color:#334155'>
<div class='note'>能量柱随同一状态更新：动能绿、势能紫、机械能灰。改参数只会重采样，页面不计算公式。</div>
<div class='note'>动能</div><div class='bar'><i id='ek' class='k'></i></div>
<div class='note'>势能</div><div class='bar'><i id='ep' class='p'></i></div>
<div class='note'>机械能</div><div class='bar'><i id='em' class='m'></i></div>
<div id='events' class='read warn'></div>
<div class='note'>提示：首屏必须停在 0 s；按“播放”才开始。拖动系统时间轴可慢放检查落地瞬间。</div>
</aside>
</div>
</main>
<script>
(function(){'use strict';
var H=globalThis.__HARNESS_INPUT__;var sc0=H.scenario;var DUR=6.5,N=327,step=DUR/(N-1);
var times=[];for(var i=0;i<N;i++){times.push(i*step)}
var $=function(id){return document.getElementById(id)};
var ids=['mode','speed','angle','y0','g','mass'];
function setv(id,v){$(id).value=v;$(id+'v').textContent=fmt(v)}
function fmt(v){var n=Number(v);return (Math.abs(n)>=10?n.toFixed(1):n.toFixed(2)).replace(/\.00$/,'.0')}
function syncMode(){var hor=$('mode').value==='horizontal';$('angle').disabled=hor;$('modev').textContent=hor?'水平抛出 θ=0':'可改角度';$('anglev').textContent=hor?'0':fmt($('angle').value)}
ids.forEach(function(id){var map={mode:'mode',speed:'speed_m_s',angle:'angle_deg',y0:'y0_m',g:'g_m_s2',mass:'mass_kg'};$(id).value=sc0[map[id]];});
$('speedv').textContent=fmt(sc0.speed_m_s);$('anglev').textContent=fmt(sc0.angle_deg);$('y0v').textContent=fmt(sc0.y0_m);$('gv').textContent=fmt(sc0.g_m_s2);$('massv').textContent=fmt(sc0.mass_kg);$('modev').textContent=sc0.mode;syncMode();
var res=coursewareModel.sample({scenario:sc0,times_s:times});
var ext={minX:-6,maxX:20,maxY:35,mech:1};
function scenarioFrom(){var m=$('mode').value;return {angle_deg:m==='horizontal'?0:Number($('angle').value),g_m_s2:Number($('g').value),mass_kg:Number($('mass').value),mode:m,speed_m_s:Number($('speed').value),x0_m:Number(sc0.x0_m),y0_m:Number($('y0').value)}}
function extents(){var xs=res.states.map(function(s){return s.x_m}),ys=res.states.map(function(s){return s.y_m});ext.minX=Math.min(-6,sc0.x0_m-2,Math.min.apply(null,xs)-2);ext.maxX=Math.max(12,res.events.range_m+5,Math.max.apply(null,xs)+3);ext.maxY=Math.max(12,Number($('y0').value)*1.18,res.events.max_height_m+4,Math.max.apply(null,ys)+2);ext.mech=Math.max(1e-6,Math.max.apply(null,res.states.map(function(s){return s.mechanical_j})))}
function X(x){return 55+(x-ext.minX)/(ext.maxX-ext.minX)*675}
function Y(y){return 320-Math.max(0,y)/ext.maxY*292}
function path(){var d='';for(var i=0;i<res.states.length;i++){var s=res.states[i];d+=(i?'L':'M')+X(s.x_m).toFixed(1)+','+Y(s.y_m).toFixed(1)+' '}$('traj').setAttribute('d',d.trim())}
function arrow(id,x1,y1,x2,y2){var e=$(id);e.setAttribute('x1',x1);e.setAttribute('y1',y1);e.setAttribute('x2',x2);e.setAttribute('y2',y2)}
function label(id,x,y,t){var e=$(id);e.setAttribute('x',x);e.setAttribute('y',y);e.textContent=t}
function stateAt(t){var k=t/step,i=Math.floor(k);if(i>=N-1)return res.states[N-1];if(i<0)return res.states[0];var a=res.states[i],b=res.states[i+1],f=k-i;var s={};for(var key in a){s[key]=a[key]+(b[key]-a[key])*f}s.t_s=t;return s}
function render(st){var t=Math.min(DUR,Math.max(0,st.physicalTimeS));var s=stateAt(t),x=X(s.x_m),y=Y(s.y_m);
$('pt').textContent=CoursewarePrimitives.formatPhysicalTime(st.physicalTimeS);$('dt').textContent=CoursewarePrimitives.formatDemoRate(st.demoRate);
$('ball').setAttribute('cx',x);$('ball').setAttribute('cy',y);$('projx').setAttribute('cx',x);$('projx').setAttribute('cy',320);$('projy').setAttribute('cx',70);$('projy').setAttribute('cy',y);
arrow('xref',x,320,x,y);arrow('yref',70,y,x,y);var sc=2.2;arrow('vxv',x,y,x+s.vx_m_s*sc,y);arrow('vyv',x,y,x,y-s.vy_m_s*sc);arrow('vv',x,y,x+s.vx_m_s*sc,y-s.vy_m_s*sc);arrow('av',x,y,x,y-Math.min(0,s.ay_m_s2)*sc*1.2);
label('tvx',x+s.vx_m_s*sc+6,y,'vx');label('tvy',x+8,y-s.vy_m_s*sc,'vy');label('ta',x-62,y+28,'a 向下');
$('ek').style.width=(100*s.kinetic_j/ext.mech)+'%';$('ep').style.width=(100*s.potential_j/ext.mech)+'%';$('em').style.width=(100*s.mechanical_j/ext.mech)+'%';
$('ro').textContent='t='+s.t_s.toFixed(2)+' s｜x='+s.x_m.toFixed(2)+' m｜y='+s.y_m.toFixed(2)+' m｜vx='+s.vx_m_s.toFixed(2)+'｜vy='+s.vy_m_s.toFixed(2)+' m/s｜E='+s.mechanical_j.toFixed(1)+' J';
$('events').textContent='落地 '+res.events.flight_time_s.toFixed(2)+' s｜射程 '+res.events.range_m.toFixed(2)+' m｜最高 '+res.events.max_height_m.toFixed(2)+' m｜等高最优角 '+res.events.optimal_equal_height_angle_deg.toFixed(1)+'°';}
function rebuild(first){var sc=first?sc0:scenarioFrom();res=coursewareModel.sample({scenario:sc,times_s:times});extents();path();tl.pause();tl.seek(0);render({physicalTimeS:0,demoRate:tlState.demoRate||1,playing:false});}
ids.forEach(function(id){$(id).addEventListener('input',function(){setv(id,$(id).value);if(id==='mode'){syncMode()}rebuild(false)})});
var tlState={demoRate:1};var tl=CoursewarePrimitives.createTimeline({durationPhysicalS:DUR,onChange:function(st){tlState=st;render(st)}});
$('play').addEventListener('click',function(){tl.play()});$('pause').addEventListener('click',function(){tl.pause()});$('replay').addEventListener('click',function(){tl.replay()});$('slow').addEventListener('click',function(){tl.setDemoRate(0.5)});$('fast').addEventListener('click',function(){tl.setDemoRate(2)});
document.addEventListener('visibilitychange',function(){if(document.hidden){tl.pause()}});
extents();path();tl.pause();tl.seek(0);render({physicalTimeS:0,demoRate:1,playing:false});
})();
</script>
</body>
</html>"}
